  function createIcon(
    kind
  ) {
    const definition =
      ICONS[kind] ||
      ICONS.hide;

    const svg =
      document.createElementNS(
        SVG_NS,
        "svg"
      );

    const compactIcon =
  kind === "collapse" ||
  kind === "expand";

const viewBoxes = {
  hide: "0 0 12 12",
  collapse: "0 0 11 11",
  expand: "0 0 11 11",
  restoreVertical: "0 0 11 17",
  restoreHorizontal: "0 0 20 13",
};

svg.setAttribute(
  "viewBox",
  viewBoxes[kind] || "0 0 20 20"
);

    svg.setAttribute(
      "aria-hidden",
      "true"
    );

    svg.setAttribute(
      "focusable",
      "false"
    );

    definition.forEach(
      (
        [
          tagName,
          attributes,
        ]
      ) => {
        const part =
          document.createElementNS(
            SVG_NS,
            tagName
          );

        Object.entries(
          attributes
        ).forEach(
          (
            [
              name,
              value,
            ]
          ) => {
            part.setAttribute(
              name,
              value
            );
          }
        );

        svg.appendChild(
          part
        );
      }
    );

    return svg;
  }

  function apply(
    button,
    options = {}
  ) {
    if (!button) {
      return null;
    }

    const kind =
      options.kind ||
      "hide";

    const label =
      options.label ||
      "";

    button.classList.add(
      "visibility-control"
    );

    button.dataset
      .visibilityIcon =
        kind;

    button.disabled =
      options.disabled ===
      true;

    button.classList.toggle(
      "is-always-visible",
      options.alwaysVisible ===
        true
    );

    if (label) {
      button.title =
        label;

      button.setAttribute(
        "aria-label",
        label
      );
    }

    button.replaceChildren(
      createIcon(kind)
    );

    return button;
  }

  function createButton(
    options = {}
  ) {
    const button =
      document.createElement(
        "button"
      );

    button.type =
      "button";

    return apply(
      button,
      options
    );
  }

  window.visibilityControls = {
    apply,
    createButton,
    createIcon,
  };
